import React from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Header from './components/Header';
import Catalog from './pages/Catalog';
import TourDetail from './pages/TourDetail';
import Player from './pages/Player';
import Evidence from './pages/Evidence';
import B2BDashboard from './pages/B2BDashboard';

function AppContent() {
  const location = useLocation();
  const isPlayer = location.pathname.startsWith('/player');
  const isEvidence = location.pathname.startsWith('/evidence');
  const isB2B = location.pathname.startsWith('/b2b');

  return (
    <div className="min-h-screen bg-slate-200 flex justify-center">
      {/* Mobile container simulation */}
      <div className="w-full max-w-md bg-[#FDFBF7] min-h-screen shadow-2xl relative overflow-x-hidden">
        {(!isPlayer && !isEvidence && !isB2B) && <Header />}
        <Routes>
          <Route path="/" element={<Catalog />} />
          <Route path="/tour/:id" element={<TourDetail />} />
          <Route path="/player/:id" element={<Player />} />
          <Route path="/evidence/:id" element={<Evidence />} />
          <Route path="/b2b" element={<B2BDashboard />} />
        </Routes>
      </div>
    </div>
  );
}

export default function App() {
  return (
    <Router basename={import.meta.env.BASE_URL}>
      <AppContent />
    </Router>
  );
}